import{_ as o,c as t,o as r,al as a}from"./chunks/framework.CT7RwC5a.js";const c=JSON.parse('{"title":"Apps & API","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_rover/api.md","filePath":"uk/flight_modes_rover/api.md"}'),s={name:"uk/flight_modes_rover/api.md"};function d(i,e,n,h,f,l){return r(),t("div",null,e[0]||(e[0]=[a('<h1 id="apps-api" tabindex="-1">Apps &amp; API <a class="header-anchor" href="#apps-api" aria-label="Permalink to &quot;Apps &amp; API&quot;">​</a></h1><p>The rover modules have been tested and integrated with a subset of the available <a href="./../middleware/">Apps &amp; API</a> methods. We specifically provide guides for using <a href="./../ros2/">ROS 2</a> to interface a companion computer with PX4 via <a href="./../middleware/uxrce_dds.html">uXRCE-DDS</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Опис</th></tr></thead><tbody><tr><td><a href="#px4-ros-2-interface">PX4 ROS 2 Interface</a> (Recommended)</td><td>Register a custom mode and publish <a href="./../ros2/px4_ros2_control_interface.html#rover-setpoints">RoverSetpointTypes</a>.</td></tr><tr><td><a href="#ros-2-offboard-control">ROS 2 Offboard Control</a></td><td>Use the PX4 internal <a href="./../flight_modes/offboard.html">Offboard Mode</a> and publish messages defined in <a href="./../middleware/dds_topics.html">dds_topics.yaml</a>.</td></tr></tbody></table><h2 id="px4-ros-2-interface" tabindex="-1">PX4 ROS 2 Interface <a class="header-anchor" href="#px4-ros-2-interface" aria-label="Permalink to &quot;PX4 ROS 2 Interface&quot;">​</a></h2><p>We recommend the use of the <a href="./../ros2/px4_ros2_interface_lib.html">PX4 ROS 2 Interface Library</a> which allows you to register a custom drive mode and exposes <a href="./../ros2/px4_ros2_control_interface.html#rover-setpoints">RoverSetpointTypes</a>.</p><p>By using these setpoints (instead of the PX4 internal rover setpoints), you are guaranteed to send valid control inputs to your vehicle and the control flags for the setpoints you are using are automatically set for you. Registering a custom drive mode instead of using <a href="#ros-2-offboard-control">ROS 2 Offboard Control</a> additionally provides the advantages listed <a href="./../concept/flight_modes.html#internal-vs-external-modes">here</a>.</p><p>To get familiar with this method, read through the guide for the <a href="./../ros2/px4_ros2_interface_lib.html">PX4 ROS 2 Interface Library</a> where we also provide an example app for rover.</p><h2 id="ros-2-offboard-control" tabindex="-1">ROS 2 Offboard Control <a class="header-anchor" href="#ros-2-offboard-control" aria-label="Permalink to &quot;ROS 2 Offboard Control&quot;">​</a></h2><p><a href="./../ros2/offboard_control.html">ROS 2 Offboard Control</a> uses the PX4 internal <a href="./../flight_modes/offboard.html">Offboard Mode</a>.</p><p>While you can subscribe/publish to all topics specified in <a href="./../middleware/dds_topics.html">dds_topics.yaml</a>, not all rover modules support all of these topics (see <a href="./../flight_modes/offboard.html#rover">Supported Setpoints</a>). Unlike the <a href="./../ros2/px4_ros2_control_interface.html#rover-setpoints">RoverSetpointTypes</a> exposed through the <a href="#px4-ros-2-interface">PX4 ROS 2 Interface</a>, there is no guarantee that the published setpoints lead to a valid control input.</p><p>In addition, the correct control mode flags must be set through <a href="./../msg_docs/OffboardControlMode.html">OffboardControlMode</a>. This requires a deeper understanding of PX4 and the structure of the rover modules. For general information on setting up offboard mode read through <a href="./../flight_modes/offboard.html">Offboard Mode</a> and then consult <a href="./../flight_modes/offboard.html#rover">Supported Setpoints</a>.</p>',11)]))}const m=o(s,[["render",d]]);export{c as __pageData,m as default};
